parameters.jsCode:
// Deterministic checks. The agent's output is a proposal; nothing here trusts it
// without comparing against config or a fresh read of the system of record.
const cfg = $('Config').first().json;
const out = $('Payment exception agent').item.json.output ?? null;
const reasons = [];
if (!out) reasons.push('agent_produced_no_valid_output');
if (out && !(typeof out.confidence === 'number' && out.confidence >= cfg.min_confidence)) {
  reasons.push('confidence ' + out?.confidence + ' below ' + cfg.min_confidence);
}

const req = $('Normalize failure event').item.json;
const p = $json; // fresh read of the payment
const rec = out?.recommendation;
const rail = rec === 'reroute' ? out?.target_rail : p.rail;
const limits = cfg.rail_limits?.[rail];

if (p.status !== 'failed') reasons.push('payment status is now ' + p.status);
if (Number(p.amount) !== req.amount) reasons.push('amount on record ' + p.amount + ' differs from event ' + req.amount);
if (rec === 'hold_for_review') reasons.push('agent recommends review');
if (out?.root_cause === 'suspected_fraud') reasons.push('suspected fraud goes to a person');
if ((rec === 'retry_same_rail' || rec === 'reroute') && (p.retry_count ?? 0) >= cfg.max_retries) reasons.push('retry limit ' + cfg.max_retries + ' reached');
if (rec === 'reroute' && !out?.target_rail) reasons.push('reroute without a target rail');
if (rec === 'reroute' && out?.target_rail === p.rail) reasons.push('reroute to the same rail');
if ((rec === 'retry_same_rail' || rec === 'reroute') && !limits) reasons.push('no limits configured for rail ' + rail);
if (limits && (p.amount < limits.min || p.amount > limits.max)) reasons.push(rail + ' cannot carry ' + p.amount + ' (limits ' + limits.min + ' to ' + limits.max + ')');
if (rec === 'refund_to_source' && p.debit_status !== 'debited') reasons.push('refund proposed but debit status is ' + p.debit_status);
if (rec === 'refund_to_source' && p.reversal_status && p.reversal_status !== 'none') reasons.push('reversal already ' + p.reversal_status);

const action = { type: rec, payment_id: p.payment_id ?? req.payment_id, rail, amount: p.amount };
const summary = 'Payment ' + req.payment_id + ' (' + req.amount + ' ' + req.currency + ' on ' + req.rail + ') failed: ' + (out?.root_cause ?? 'unknown') + '.\n'
  + 'Proposed: *' + rec + '*' + (rec === 'reroute' ? ' via ' + rail : '') + '.\n' + (out?.rationale ?? '');
const ok = reasons.length === 0;
const isNoop = typeof noop !== 'undefined' && noop === true;
const route = !ok ? 'escalate' : isNoop ? 'none' : 'approve';
return { json: { business_key: req.business_key, route, guardrail_reasons: reasons, action, approval_summary: summary, planned_actions: ok && !isNoop ? [action] : [] } };

// The approval request goes to one named person, so the approver is that person.
// Slack returns { data: { approved, respondedAt } }; a timeout resumes without it.
const cfg = $('Config').first().json;
const approved = $json.data?.approved;
return {
  json: {
    decision: approved === true ? 'approved' : approved === false ? 'declined' : 'timed_out',
    approver: cfg.approver_slack_user,
    decided_at: $json.data?.respondedAt ?? new Date().toISOString(),
    handoff_reason: approved === true || approved === false ? '' : 'approval timed out after ' + cfg.approval_timeout_hours + ' hours',
  },
};

// Done only when the system of record shows what was planned.
const planned = $('Guardrails').item.json.action;
const expected = planned.type === 'refund_to_source' ? ['reversal_initiated', 'reversed'] : ['pending', 'processing', 'settled'];
const ok = expected.includes($json.status) && (planned.type === 'refund_to_source' || $json.rail === planned.rail);
const detail = 'payment shows status ' + $json.status + ' on ' + $json.rail + ', expected ' + expected.join('/') + (planned.type === 'refund_to_source' ? '' : ' on ' + planned.rail);
return { json: { verified: ok, verify_failed: !ok, verify_detail: ok ? '' : detail } };

// Collects everything a reviewer needs in one record: the request, what the agent
// proposed, why the guardrails stopped it, and the tool calls behind it.
const intake = $('Normalize failure event').item.json;
let agent = null;
let guard = null;
try { agent = $('Payment exception agent').item.json; } catch (e) {}
try { guard = $('Guardrails').item.json; } catch (e) {}

const reasons = [...(guard?.guardrail_reasons ?? [])];
if ($json.error) reasons.push('system_error: ' + ($json.error.message ?? JSON.stringify($json.error)).slice(0, 300));
if ($json.verify_failed) reasons.push('verification_failed: ' + $json.verify_detail);
if ($json.handoff_reason) reasons.push($json.handoff_reason);
if (!agent?.output && !reasons.length) reasons.push('agent_produced_no_valid_output');
if (!reasons.length) {
  const o = agent.output;
  reasons.push('agent recommends review: ' + (o.decision ?? o.recommended_action ?? o.classification ?? o.route_to_queue ?? 'see proposal'));
}

const trace = (agent?.intermediateSteps ?? []).map((s) => ({
  tool: s.action?.tool,
  input: s.action?.toolInput,
  observation: String(s.observation ?? '').slice(0, 1500),
}));

return {
  json: {
    business_key: intake.business_key,
    team: "payments operations",
    reasons,
    proposed: agent?.output ?? null,
    confidence: agent?.output?.confidence ?? null,
    questions: agent?.output?.questions_for_human ?? [],
    trace,
    summary: 'Payment ' + intake.payment_id + ' · ' + intake.rail + ' · ' + intake.amount + ' ' + intake.currency + ' · proposed ' + (agent?.output?.recommendation ?? 'none'),
  },
};

